-- INSERT on university_email_domains
INSERT INTO university_email_domains (university_id, domain, domain_type)
SELECT id, email_domain, 'general'
FROM universities
WHERE email_domain IS NOT NULL
ON CONFLICT (university_id, domain, domain_type) DO NOTHING;

-- INSERT on university_email_domains
INSERT INTO university_email_domains (university_id, domain, domain_type)
SELECT id, 'student.' || email_domain, 'student'
FROM universities
WHERE email_domain IS NOT NULL AND is_partner = TRUE
ON CONFLICT (university_id, domain, domain_type) DO NOTHING;

-- INSERT on university_partnerships
INSERT INTO university_partnerships (
    university_id, partnership_type, discount_percentage, benefits,
    active, contract_start_date, contract_end_date, contact_email
)
SELECT
    id,
    CASE
        WHEN student_discount_percentage >= 22 THEN 'premium'
        WHEN student_discount_percentage >= 15 THEN 'basic'
        ELSE 'basic'
    END,
    student_discount_percentage,
    jsonb_build_object(
        'priority_support', TRUE,
        'verified_status', TRUE,
        'community_access', TRUE,
        'discount_housing', TRUE,
        'premium_features', student_discount_percentage >= 18,
        'early_access', student_discount_percentage >= 22
    ),
    TRUE,
    CURRENT_DATE - INTERVAL '6 months',
    CURRENT_DATE + INTERVAL '2 years',
    'partnerships@' || email_domain
FROM universities
WHERE is_partner = TRUE
ON CONFLICT (university_id) DO UPDATE SET
    partnership_type = EXCLUDED.partnership_type,
    benefits = EXCLUDED.benefits,
    updated_at = NOW();

