-- UPDATE on notifications
UPDATE notifications
SET category = 'system'
WHERE category NOT IN (
    'match',
    'message',
    'community',
    'admin',
    'system',
    'property_interest',
    'viewing_request',
    'property_management',
    'maintenance_request',
    'payment',
    'verification',
    'subscription'
);

-- UPDATE on subscription_plans
UPDATE subscription_plans
SET features = features || jsonb_build_object(
    'max_ai_chats_per_day', 3,
    'ai_chat_enabled', true,
    'ai_chat_file_uploads', true,
    'ai_chat_history_retention_days', 30
)
WHERE plan_code = 'essentials'
AND NOT (features ? 'max_ai_chats_per_day');

