-- UPDATE on roommate_listings
UPDATE roommate_listings
SET slug = LOWER(
  REGEXP_REPLACE(
    REGEXP_REPLACE(
      title || '-' || SUBSTRING(id::TEXT FROM 1 FOR 8),
      '[^a-zA-Z0-9\s-]', '', 'g'
    ),
    '\s+', '-', 'g'
  )
)
WHERE slug IS NULL;

