-- INSERT on email_templates
INSERT INTO email_templates (name, subject, body_html, body_text, template_type, locale, template_variables) VALUES
(
  'new_match',
  'New Match on MyRoomie!',
  '<!DOCTYPE html>
<html>
<head><title>New Match</title></head>
<body style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
  <div style="background: linear-gradient(135deg, #3b82f6, #1d4ed8); color: white; padding: 20px; border-radius: 8px; text-align: center;">
    <h1 style="margin: 0;">✨ You have a new match!</h1>
  </div>
  <div style="padding: 20px; background: #f9fafb; border-radius: 8px; margin: 20px 0;">
    <p>Hi {{userName}},</p>
    <p>Great news! Someone is interested in connecting with you on MyRoomie.</p>
    <div style="text-align: center; margin: 30px 0;">
      <a href="{{appUrl}}/matches" style="background: #3b82f6; color: white; padding: 15px 30px; text-decoration: none; border-radius: 6px; display: inline-block; font-weight: bold;">View Match</a>
    </div>
    <p style="color: #6b7280;">Happy room hunting!</p>
    <p style="color: #6b7280;">The MyRoomie Team</p>
  </div>
</body>
</html>',
  'Hi {{userName}}, You have a new match on MyRoomie! Visit {{appUrl}}/matches to see more. Happy room hunting! - The MyRoomie Team',
  'notification',
  'en',
  '["userName", "appUrl"]'::jsonb
),
(
  'new_message',
  'New Message on MyRoomie',
  '<!DOCTYPE html>
<html>
<head><title>New Message</title></head>
<body style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
  <div style="background: linear-gradient(135deg, #10b981, #047857); color: white; padding: 20px; border-radius: 8px; text-align: center;">
    <h1 style="margin: 0;">💬 New message received</h1>
  </div>
  <div style="padding: 20px; background: #f9fafb; border-radius: 8px; margin: 20px 0;">
    <p>Hi {{userName}},</p>
    <p><strong>From:</strong> {{senderName}}</p>
    <p><strong>Message preview:</strong> {{messagePreview}}</p>
    <div style="text-align: center; margin: 30px 0;">
      <a href="{{appUrl}}/messages" style="background: #10b981; color: white; padding: 15px 30px; text-decoration: none; border-radius: 6px; display: inline-block; font-weight: bold;">Reply Now</a>
    </div>
    <p style="color: #6b7280;">Best regards,</p>
    <p style="color: #6b7280;">The MyRoomie Team</p>
  </div>
</body>
</html>',
  'Hi {{userName}}, New message from {{senderName}}: {{messagePreview}}. Visit {{appUrl}}/messages to reply. - The MyRoomie Team',
  'notification',
  'en',
  '["userName", "senderName", "messagePreview", "appUrl"]'::jsonb
),
(
  'welcome',
  'Welcome to MyRoomie! 🏠',
  '<!DOCTYPE html>
<html>
<head><title>Welcome</title></head>
<body style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
  <div style="background: linear-gradient(135deg, #8b5cf6, #6d28d9); color: white; padding: 30px; border-radius: 8px; text-align: center;">
    <h1 style="margin: 0;">Welcome to MyRoomie!</h1>
    <p style="margin: 10px 0 0 0;">Find your perfect roommate match</p>
  </div>
  <div style="padding: 20px; background: #f9fafb; border-radius: 8px; margin: 20px 0;">
    <p>Hi {{userName}},</p>
    <p>Welcome to MyRoomie! We''re excited to help you find your perfect roommate.</p>
    <p><strong>Next steps:</strong></p>
    <ul>
      <li>Complete your profile</li>
      <li>Take the personality test</li>
      <li>Set your lifestyle preferences</li>
      <li>Start browsing matches</li>
    </ul>
    <div style="text-align: center; margin: 30px 0;">
      <a href="{{appUrl}}/onboarding" style="background: #8b5cf6; color: white; padding: 15px 30px; text-decoration: none; border-radius: 6px; display: inline-block; font-weight: bold;">Complete Profile</a>
    </div>
    <p style="color: #6b7280;">Best of luck on your roommate journey!</p>
    <p style="color: #6b7280;">The MyRoomie Team</p>
  </div>
</body>
</html>',
  'Welcome to MyRoomie! Complete your profile at {{appUrl}}/onboarding to start finding your perfect roommate. - The MyRoomie Team',
  'transactional',
  'en',
  '["userName", "appUrl"]'::jsonb
),
(
  'verification_email',
  'Verify Your MyRoomie Account',
  '<!DOCTYPE html>
<html>
<head><title>Verify Account</title></head>
<body style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
  <div style="padding: 20px; background: #f9fafb; border-radius: 8px;">
    <h1>Verify Your Account</h1>
    <p>Hi {{userName}},</p>
    <p>Please verify your email address to complete your MyRoomie registration.</p>
    <div style="text-align: center; margin: 30px 0;">
      <a href="{{verificationLink}}" style="background: #3b82f6; color: white; padding: 15px 30px; text-decoration: none; border-radius: 6px; display: inline-block; font-weight: bold;">Verify Email</a>
    </div>
    <p style="color: #6b7280; font-size: 12px;">If you didn''t create this account, please ignore this email.</p>
  </div>
</body>
</html>',
  'Verify your MyRoomie account: {{verificationLink}}',
  'transactional',
  'en',
  '["userName", "verificationLink"]'::jsonb
),
(
  'password_reset',
  'Reset Your MyRoomie Password',
  '<!DOCTYPE html>
<html>
<head><title>Password Reset</title></head>
<body style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
  <div style="padding: 20px; background: #f9fafb; border-radius: 8px;">
    <h1>Password Reset Request</h1>
    <p>Hi {{userName}},</p>
    <p>We received a request to reset your password. Click the button below to create a new password:</p>
    <div style="text-align: center; margin: 30px 0;">
      <a href="{{resetLink}}" style="background: #ef4444; color: white; padding: 15px 30px; text-decoration: none; border-radius: 6px; display: inline-block; font-weight: bold;">Reset Password</a>
    </div>
    <p style="color: #6b7280; font-size: 12px;">If you didn''t request this, please ignore this email. This link expires in 24 hours.</p>
  </div>
</body>
</html>',
  'Reset your password: {{resetLink}}. This link expires in 24 hours.',
  'transactional',
  'en',
  '["userName", "resetLink"]'::jsonb
)
ON CONFLICT (name) DO UPDATE SET
  subject = EXCLUDED.subject,
  body_html = EXCLUDED.body_html,
  body_text = EXCLUDED.body_text,
  template_variables = EXCLUDED.template_variables,
  template_type = EXCLUDED.template_type,
  locale = EXCLUDED.locale,
  updated_at = NOW();

