-- INSERT on mbti_personality_types
INSERT INTO mbti_personality_types (code, name, description, strengths, challenges, living_style, ideal_roommate_types, locale) VALUES
(
  'ENFJ',
  'The Social Coordinator',
  'You thrive on creating harmony and bringing flatmates together. Natural organizers who ensure everyone feels included and the household runs smoothly.',
  '["Excellent at mediating conflicts", "Organizes group activities and events", "Sensitive to everyone''s needs", "Creates a warm, welcoming atmosphere", "Great at communication and planning"]'::jsonb,
  '["May take on too much responsibility for others", "Can be overwhelmed by household tensions", "Might neglect own needs for the group", "May be hurt by lack of appreciation"]'::jsonb,
  'Creates a harmonious, socially active household where everyone feels valued and included.',
  '["INFP", "ISFP", "ENTP", "ENFP"]'::jsonb,
  'en'
),
(
  'INFJ',
  'The Thoughtful Harmonizer',
  'You prefer a peaceful, organized home environment with meaningful connections. Values deep relationships with flatmates and creates a calm, inspiring space.',
  '["Creates a peaceful, organized environment", "Excellent listener and confidant", "Anticipates needs before problems arise", "Brings depth to household relationships", "Diplomatic conflict resolution"]'::jsonb,
  '["May withdraw when overwhelmed", "Can be perfectionistic about home environment", "Might struggle with too much social activity", "May keep concerns to themselves"]'::jsonb,
  'Maintains a serene, well-organized home with emphasis on quality relationships over quantity.',
  '["ENFJ", "ENFP", "INFP", "ENTP"]'::jsonb,
  'en'
),
(
  'INTJ',
  'The Strategic Planner',
  'You value efficiency and independence in your living space. Prefers a well-organized, quiet environment with clear boundaries and logical systems.',
  '["Excellent at creating efficient systems", "Respects boundaries and privacy", "Problem-solver for household issues", "Self-sufficient and low-maintenance", "Strategic thinking for shared expenses"]'::jsonb,
  '["May seem distant or aloof", "Can be overly critical of inefficiency", "Might struggle with emotional conversations", "May prefer solitude over social interaction"]'::jsonb,
  'Maintains an efficient, organized household with clear systems and respect for personal space.',
  '["ENFP", "ENTP", "INTJ", "INFJ"]'::jsonb,
  'en'
),
(
  'INTP',
  'The Analytical Observer',
  'You appreciate a flexible, low-key living arrangement. Values intellectual space and creative freedom with minimal drama.',
  '["Adaptable and easygoing", "Interesting conversations and insights", "Respects personal space", "Creative problem-solving", "Low-maintenance roommate"]'::jsonb,
  '["May forget chores or responsibilities", "Can be detached from household matters", "Might avoid conflict or decisions", "May need reminders for social obligations"]'::jsonb,
  'Prefers a relaxed, intellectually stimulating environment with flexible arrangements.',
  '["ENTJ", "ENFJ", "INFJ", "INTP"]'::jsonb,
  'en'
),
(
  'ENTJ',
  'The Executive Organizer',
  'You bring structure and leadership to shared living. Takes initiative in organizing household matters and ensuring everything runs efficiently.',
  '["Natural leader for household decisions", "Excellent at organizing and planning", "Direct communication style", "Takes initiative on problems", "Efficient with shared resources"]'::jsonb,
  '["Can be domineering or controlling", "May be impatient with inefficiency", "Might overwhelm quieter roommates", "Can be too focused on productivity"]'::jsonb,
  'Creates a well-structured, efficient household with clear roles and expectations.',
  '["INFP", "INTP", "ENFP", "ENTJ"]'::jsonb,
  'en'
),
(
  'ENTP',
  'The Energetic Debater',
  'You bring energy and spontaneity to shared living. Enjoys engaging discussions and trying new approaches to household matters.',
  '["Brings fun and spontaneity", "Great at brainstorming solutions", "Adaptable to change", "Interesting conversationalist", "Creative problem-solving"]'::jsonb,
  '["Can be argumentative or provocative", "May start projects without finishing", "Might disrupt routines", "Can be scattered with responsibilities"]'::jsonb,
  'Maintains a dynamic, flexible household with plenty of discussion and experimentation.',
  '["INFJ", "INTJ", "ENFJ", "ENTP"]'::jsonb,
  'en'
),
(
  'INFP',
  'The Gentle Idealist',
  'You value authenticity and harmony in your living space. Creates a warm, creative environment where everyone can be themselves.',
  '["Empathetic and understanding", "Creates peaceful atmosphere", "Respects individuality", "Good listener", "Flexible and accommodating"]'::jsonb,
  '["May avoid confrontation", "Can be overly sensitive to criticism", "Might struggle with practical tasks", "May retreat when stressed"]'::jsonb,
  'Fosters a peaceful, accepting home where creativity and individuality are valued.',
  '["ENFJ", "ENTJ", "INFP", "ENFP"]'::jsonb,
  'en'
),
(
  'ENFP',
  'The Enthusiastic Connector',
  'You bring warmth and creativity to shared living. Loves creating meaningful connections and a vibrant home atmosphere.',
  '["Warm and enthusiastic", "Brings people together", "Creative and fun", "Supportive and encouraging", "Adaptable to different personalities"]'::jsonb,
  '["Can be scattered with chores", "May overcommit to social activities", "Might struggle with routine tasks", "Can be emotionally intense"]'::jsonb,
  'Creates a warm, lively household full of creativity, conversation, and connection.',
  '["INTJ", "INFJ", "ENTJ", "ENFP"]'::jsonb,
  'en'
),
(
  'ISTJ',
  'The Reliable Organizer',
  'You value stability, routine, and responsibility. Creates a dependable, well-maintained household where commitments are honored.',
  '["Highly reliable and responsible", "Excellent with household maintenance", "Respects rules and agreements", "Organized and systematic", "Financially responsible"]'::jsonb,
  '["Can be inflexible with changes", "May be critical of mess or disorder", "Might struggle with spontaneity", "Can seem reserved or formal"]'::jsonb,
  'Maintains a stable, well-organized household with clear rules and routines.',
  '["ESTP", "ESFP", "ISTJ", "ESTJ"]'::jsonb,
  'en'
),
(
  'ISFJ',
  'The Caring Supporter',
  'You create a nurturing, comfortable home environment. Takes pride in maintaining a clean, welcoming space for everyone.',
  '["Thoughtful and caring", "Maintains clean, comfortable space", "Remembers preferences and needs", "Reliable and dutiful", "Creates homey atmosphere"]'::jsonb,
  '["May take on too much responsibility", "Can be hurt by lack of appreciation", "Might avoid necessary conflict", "May be overly traditional"]'::jsonb,
  'Creates a warm, well-maintained home where everyone feels cared for and comfortable.',
  '["ESFP", "ESTP", "ISFJ", "ESFJ"]'::jsonb,
  'en'
),
(
  'ESTJ',
  'The Practical Manager',
  'You bring order and efficiency to shared living. Takes charge of practical matters and ensures household responsibilities are met.',
  '["Excellent at managing household", "Direct and clear communication", "Takes responsibility seriously", "Organized and efficient", "Good with finances and planning"]'::jsonb,
  '["Can be rigid or controlling", "May be impatient with disorder", "Might be overly critical", "Can prioritize rules over flexibility"]'::jsonb,
  'Runs an efficient, well-organized household with clear expectations and accountability.',
  '["ISFP", "INFP", "ESTJ", "ISTJ"]'::jsonb,
  'en'
),
(
  'ESFJ',
  'The Warm Host',
  'You excel at creating a welcoming, harmonious home. Naturally attentive to others'' needs and comfort in shared spaces.',
  '["Creates warm, welcoming atmosphere", "Attentive to everyone''s needs", "Excellent at organizing social events", "Maintains harmony", "Great communication skills"]'::jsonb,
  '["May be hurt by conflict", "Can be overly concerned with others'' opinions", "Might struggle with change", "May take criticism personally"]'::jsonb,
  'Maintains a warm, social household where everyone feels welcome and included.',
  '["ISFP", "ISTP", "ESFJ", "ISFJ"]'::jsonb,
  'en'
),
(
  'ISTP',
  'The Practical Problem-Solver',
  'You value independence and practicality. Excellent at fixing things and handling household emergencies with calm efficiency.',
  '["Great at fixing things", "Calm in emergencies", "Low-maintenance roommate", "Respects personal space", "Practical and resourceful"]'::jsonb,
  '["Can be detached or aloof", "May avoid social obligations", "Might be messy with own space", "Can be unpredictable"]'::jsonb,
  'Prefers a flexible, low-drama household where everyone handles their own responsibilities.',
  '["ESFJ", "ESTJ", "ISTP", "ESTP"]'::jsonb,
  'en'
),
(
  'ISFP',
  'The Gentle Artist',
  'You bring creativity and adaptability to shared living. Creates a peaceful, aesthetically pleasing environment.',
  '["Creates beautiful, peaceful space", "Easygoing and adaptable", "Respects individuality", "Artistic and creative", "Avoids conflict"]'::jsonb,
  '["May avoid confrontation", "Can be too accommodating", "Might struggle with schedules", "May be sensitive to criticism"]'::jsonb,
  'Maintains a peaceful, artistic household where creativity and individuality are valued.',
  '["ENFJ", "ESFJ", "ESTJ", "ISFP"]'::jsonb,
  'en'
),
(
  'ESTP',
  'The Energetic Doer',
  'You bring energy and spontaneity to shared living. Enjoys an active, social household with plenty of excitement.',
  '["Brings fun and energy", "Practical problem-solver", "Socially engaging", "Adaptable and flexible", "Takes action quickly"]'::jsonb,
  '["Can be impulsive", "May prioritize fun over responsibilities", "Might be too loud or active", "Can be impatient with routine"]'::jsonb,
  'Creates a lively, active household with spontaneous social activities.',
  '["ISFJ", "ISTJ", "ESTP", "ESFP"]'::jsonb,
  'en'
),
(
  'ESFP',
  'The Entertaining Host',
  'You create a fun, vibrant home atmosphere. Loves socializing and ensuring everyone is having a good time.',
  '["Creates fun, lively atmosphere", "Warm and friendly", "Great at hosting", "Spontaneous and exciting", "Positive energy"]'::jsonb,
  '["Can be scattered with responsibilities", "May struggle with routine tasks", "Might be too loud or social", "Can avoid serious discussions"]'::jsonb,
  'Maintains a vibrant, social household full of fun, spontaneity, and entertainment.',
  '["ISTJ", "ISFJ", "ESFP", "ESTP"]'::jsonb,
  'en'
)
ON CONFLICT (code, locale) DO UPDATE SET
