INSERT INTO error_messages (error_code, title, message, suggested_action, locale) VALUES
('AUTH_FAILED', 'Authentication Failed', 'Unable to authenticate your request. Please sign in again.', 'Sign in to continue', 'en'),
('NOT_FOUND', 'Not Found', 'The requested resource could not be found.', 'Check the URL and try again', 'en'),
('SERVER_ERROR', 'Server Error', 'An unexpected error occurred. Please try again later.', 'Try again or contact support', 'en'),
('VALIDATION_ERROR', 'Validation Error', 'The information provided is invalid or incomplete.', 'Check your input and try again', 'en'),
('PERMISSION_DENIED', 'Permission Denied', 'You don''t have permission to perform this action.', 'Contact an administrator if you need access', 'en'),
('RATE_LIMIT', 'Too Many Requests', 'You''ve made too many requests. Please slow down.', 'Wait a moment and try again', 'en'),
('PAYMENT_FAILED', 'Payment Failed', 'We couldn''t process your payment.', 'Check your payment details and try again', 'en'),
('PROFILE_INCOMPLETE', 'Profile Incomplete', 'Please complete your profile to continue.', 'Complete your profile now', 'en'),
('VERIFICATION_REQUIRED', 'Verification Required', 'Please verify your account to access this feature.', 'Complete verification', 'en'),
