-- INSERT on faq_content
INSERT INTO faq_content (category, question, answer, tags, locale, sort_order) VALUES
('getting_started', 'How do I create an account?', 'Click the "Sign Up" button in the top right corner and follow the registration process. You''ll need to provide your email, create a password, and complete your profile.', '["account", "registration"]'::jsonb, 'en', 1),
('getting_started', 'Is MyRoomie free to use?', 'Yes! MyRoomie offers a free tier with basic features. Premium subscriptions unlock advanced matching algorithms, unlimited messages, and priority support.', '["pricing", "free"]'::jsonb, 'en', 2),
('matching', 'How does the matching algorithm work?', 'Our algorithm considers personality types (MBTI), lifestyle preferences, location, budget, and move-in dates to find compatible roommates. We use sophisticated scoring to ensure quality matches.', '["algorithm", "compatibility"]'::jsonb, 'en', 1),
('matching', 'Can I filter my matches?', 'Yes! Premium users can filter by age, occupation, interests, cleanliness level, and more. Free users get smart matches based on our algorithm.', '["filters", "search"]'::jsonb, 'en', 2),
('safety', 'How do you verify users?', 'We offer ID verification, email verification, and social media linking. Verified profiles get a badge and rank higher in search results.', '["verification", "safety"]'::jsonb, 'en', 1),
('safety', 'What if I have a problem with a match?', 'You can report or block any user. We take safety seriously and investigate all reports promptly. Contact support@myroomie.com for urgent issues.', '["reporting", "support"]'::jsonb, 'en', 2),
('payments', 'What payment methods do you accept?', 'We accept all major credit cards, debit cards, and PayPal through our secure payment processor Stripe.', '["payment", "billing"]'::jsonb, 'en', 1),
('payments', 'Can I cancel my subscription?', 'Yes, you can cancel anytime from your account settings. You''ll retain access until the end of your billing period.', '["cancellation", "subscription"]'::jsonb, 'en', 2),
('account', 'How do I delete my account?', 'Go to Settings > Account > Delete Account. This action is permanent and cannot be undone.', '["deletion", "privacy"]'::jsonb, 'en', 1),
('account', 'How do I change my password?', 'Go to Settings > Security > Change Password. You''ll need your current password to set a new one.', '["password", "security"]'::jsonb, 'en', 2)
ON CONFLICT (category, question, locale) DO UPDATE SET
  answer = EXCLUDED.answer,
  tags = EXCLUDED.tags,
  sort_order = EXCLUDED.sort_order,
  updated_at = NOW();

