-- SELECT on select_statement
SELECT
    column_name,
    data_type,
    is_nullable,
    column_default
FROM information_schema.columns
WHERE table_schema = 'public'
AND table_name = 'profiles'
AND column_name IN ('username', 'privacy_settings', 'notification_preferences', 'portfolio_size')
ORDER BY ordinal_position;

