-- UPDATE on properties
UPDATE properties p
SET
  fairrent_score = fs.score,
  fairrent_letter_grade = fs.letter_grade,
  fairrent_verdict = fs.verdict,
  fairrent_calculated_at = fs.calculated_at,
  fairrent_expires_at = fs.expires_at,
  fairrent_monthly_savings = fs.monthly_savings,
  fairrent_market_price_per_sqm = fs.market_price_per_sqm,
  fairrent_actual_price_per_sqm = fs.actual_price_per_sqm
FROM (
  SELECT DISTINCT ON (property_id)
    property_id,
    score,
    letter_grade,
    verdict,
    calculated_at,
    expires_at,
    monthly_savings,
    market_price_per_sqm,
    actual_price_per_sqm
  FROM fairrent_scores
  WHERE expires_at > NOW()  -- Only migrate non-expired scores
  ORDER BY property_id, calculated_at DESC  -- Most recent score per property
) fs
WHERE p.id = fs.property_id;

-- UPDATE on rooms
UPDATE rooms r
SET
  fairrent_score = frs.score,
  fairrent_letter_grade = frs.letter_grade,
  fairrent_verdict = frs.verdict,
  fairrent_calculated_at = frs.calculated_at,
  fairrent_expires_at = frs.expires_at,
  fairrent_monthly_savings = frs.monthly_savings,
  fairrent_market_price_per_sqm = frs.market_price_per_sqm,
  fairrent_actual_price_per_sqm = frs.actual_price_per_sqm
FROM (
  SELECT DISTINCT ON (room_id)
    room_id,
    score,
    letter_grade,
    verdict,
    calculated_at,
    expires_at,
    monthly_savings,
    market_price_per_sqm,
    actual_price_per_sqm
  FROM fairrent_room_scores
  WHERE expires_at > NOW()  -- Only migrate non-expired scores
  ORDER BY room_id, calculated_at DESC  -- Most recent score per room
) frs
WHERE r.id = frs.room_id;

-- UPDATE on properties
UPDATE properties
SET slug = LOWER(
  REGEXP_REPLACE(
    REGEXP_REPLACE(
      COALESCE(title, 'property') || '-' || SUBSTRING(id::TEXT FROM 1 FOR 8),
      '[^a-zA-Z0-9\s-]', '', 'g'
    ),
    '\s+', '-', 'g'
  )
)
WHERE slug IS NULL;

-- UPDATE on profiles
UPDATE profiles
SET slug = LOWER(
  REGEXP_REPLACE(
    REGEXP_REPLACE(
      COALESCE(name, 'user') || '-' || SUBSTRING(id::TEXT FROM 1 FOR 8),
      '[^a-zA-Z0-9\s-]', '', 'g'
    ),
    '\s+', '-', 'g'
  )
)
WHERE slug IS NULL;

